export default defineComponent({
  name: "MainLayout",
  components: {
    EssentialLink,
  },
  setup() {
    const route = useRoute();
    const router = useRouter();
    const leftDrawerOpen = ref(false);
    const miniState = ref(false);
    const searchText = ref("");
    const $q = useQuasar();
    const logout = () => {
      localStorage.clear();
      router.push("/login");
    };
    const logoUrl = ref("");
    const site_title = ref("");

    const userName = ref("");
    const userBalance = ref("•••••");
    const isBalanceVisible = ref(false);

    const getUserData = () => {
      authServices
        .getUserData()
        .then((res) => {
          userName.value = res.data?.data?.full_name || "";


          $q.loading.hide();
        })
        .catch((error) => {
          $q.loading.hide();
        });
    };

    const usercurrency = ref("");

    const getlogo = () => {
      authServices.getLogo().then((res) => {
        logoUrl.value = res.data?.data?.company.logo;
        site_title.value = res.data?.data?.company.site_title;
        usercurrency.value = res.data?.data?.company.currency || "";
        })
        .catch((error) => {
          console.error("Error fetching logo:", error);
        });
    };


    const getUserBalance = () => {
      authServices.getUserBalance().then((res) => {
          userBalance.value = res.data?.data?.balance || "";
        })
        .catch((error) => {
        });
    };

    const pageTitel = computed(() => route.meta.pageTitel);
    const cramp = computed(() => route.meta.subTitle);
    const pageLink = computed(() => decodeURIComponent(route.fullPath));
    const titleOfSubTitel = computed(() => route.meta.titleOfSubTitel);

    const parentLink = computed(() =>
      route.matched.length > 1 ? route.matched[1].path : "",
    );

    const subTitleChildLink = computed(() => {
      const pathParts = route.path.split("/");
      const index = pathParts.indexOf(route.params.id);
      return index !== -1
        ? pathParts.slice(0, index - 1).join("/")
        : pathParts.slice(0, -1).join("/") || "/";
    });

    onMounted(() => {
      getUserData();
      getlogo();
    });

    return {
      essentialLinks: linksList,
      leftDrawerOpen,
      miniState,
      searchText,
      pageTitel,
      logoUrl,
      userName,
      userBalance,
      isBalanceVisible,
      site_title,
      pageLink,
      cramp,
      parentLink,
      titleOfSubTitel,
      subTitleChildLink,
      usercurrency,
      getUserBalance,
      drawerWidth: 264,
      logout,
      toggleLeftDrawer() {
        leftDrawerOpen.value = !leftDrawerOpen.value;
      },
    };
  },
});
</script>
